CREATE TABLE IF NOT EXISTS schema_migrations(version INTEGER PRIMARY KEY, applied_at TEXT NOT NULL);
CREATE TABLE roles(id INTEGER PRIMARY KEY, name TEXT NOT NULL UNIQUE, description TEXT NOT NULL DEFAULT '');
CREATE TABLE categories(id INTEGER PRIMARY KEY, name TEXT NOT NULL UNIQUE);
CREATE TABLE users(id INTEGER PRIMARY KEY, email TEXT NOT NULL UNIQUE COLLATE NOCASE, password_hash TEXT NOT NULL, name TEXT NOT NULL, employee_code TEXT NOT NULL UNIQUE, access TEXT NOT NULL CHECK(access IN ('admin','employee')), role_id INTEGER NOT NULL REFERENCES roles(id), active INTEGER NOT NULL DEFAULT 1 CHECK(active IN(0,1)), joining_date TEXT NOT NULL, timezone TEXT NOT NULL DEFAULT 'Asia/Karachi', workdays TEXT NOT NULL DEFAULT '[1,2,3,4,5]', deadline TEXT NOT NULL DEFAULT '22:00', notifications INTEGER NOT NULL DEFAULT 1, email_notifications INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL);
CREATE TABLE user_categories(user_id INTEGER NOT NULL REFERENCES users(id),category_id INTEGER NOT NULL REFERENCES categories(id),PRIMARY KEY(user_id,category_id));
CREATE TABLE sessions(token_hash TEXT PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id),csrf TEXT NOT NULL,expires_at TEXT NOT NULL);
CREATE INDEX sessions_user ON sessions(user_id);
CREATE TABLE login_attempts(key TEXT PRIMARY KEY,count INTEGER NOT NULL,last_at TEXT NOT NULL);
CREATE TABLE settings(id INTEGER PRIMARY KEY CHECK(id=1),value TEXT NOT NULL);
CREATE TABLE holidays(id INTEGER PRIMARY KEY,date TEXT NOT NULL UNIQUE,name TEXT NOT NULL);
CREATE TABLE leave_days(id INTEGER PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id),start_date TEXT NOT NULL,end_date TEXT NOT NULL,reason TEXT NOT NULL,approved INTEGER NOT NULL DEFAULT 1,CHECK(start_date<=end_date));
CREATE TABLE kpis(id INTEGER PRIMARY KEY,name TEXT NOT NULL,description TEXT NOT NULL,category_id INTEGER NOT NULL REFERENCES categories(id),unit TEXT NOT NULL,kind TEXT NOT NULL CHECK(kind IN('achievement','quality','impact')),active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE assignments(id INTEGER PRIMARY KEY,kpi_id INTEGER NOT NULL REFERENCES kpis(id),user_id INTEGER NOT NULL REFERENCES users(id),target REAL NOT NULL CHECK(target>0),frequency TEXT NOT NULL CHECK(frequency IN('daily','weekly','monthly')),start_date TEXT NOT NULL,end_date TEXT,weight REAL NOT NULL CHECK(weight>0),minimum_quality REAL CHECK(minimum_quality IS NULL OR (minimum_quality>=0 AND minimum_quality<=100)),created_at TEXT NOT NULL,CHECK(end_date IS NULL OR end_date>=start_date));
CREATE INDEX assignments_user_date ON assignments(user_id,start_date,end_date);
CREATE TABLE scoring_configs(id INTEGER PRIMARY KEY,user_id INTEGER REFERENCES users(id),role_id INTEGER REFERENCES roles(id),effective_date TEXT NOT NULL,weights TEXT NOT NULL,cap REAL NOT NULL CHECK(cap>=100 AND cap<=200),bands TEXT NOT NULL,created_at TEXT NOT NULL,CHECK(user_id IS NULL OR role_id IS NULL));
CREATE TABLE reports(id INTEGER PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id),date TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN('draft','submitted','correction_requested','corrected','approved')),achievements TEXT NOT NULL DEFAULT '',blockers TEXT NOT NULL DEFAULT '',missed_reason TEXT NOT NULL DEFAULT '',lessons TEXT NOT NULL DEFAULT '',suggestions TEXT NOT NULL DEFAULT '',next_plan TEXT NOT NULL DEFAULT '',assistance TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL,updated_at TEXT NOT NULL,submitted_at TEXT,version INTEGER NOT NULL DEFAULT 1,UNIQUE(user_id,date));
CREATE TABLE activities(id INTEGER PRIMARY KEY,report_id INTEGER NOT NULL REFERENCES reports(id),category_id INTEGER NOT NULL REFERENCES categories(id),assignment_id INTEGER REFERENCES assignments(id),title TEXT NOT NULL,description TEXT NOT NULL,actual REAL NOT NULL CHECK(actual>=0),unit TEXT NOT NULL,outcome TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN('in_progress','completed','blocked')),minutes REAL NOT NULL DEFAULT 0 CHECK(minutes>=0),evidence TEXT NOT NULL DEFAULT '',notes TEXT NOT NULL DEFAULT '');
CREATE UNIQUE INDEX one_kpi_per_report ON activities(report_id,assignment_id) WHERE assignment_id IS NOT NULL;
CREATE INDEX activities_report ON activities(report_id);
CREATE TABLE feedback(id INTEGER PRIMARY KEY,report_id INTEGER REFERENCES reports(id),user_id INTEGER NOT NULL REFERENCES users(id),actor_id INTEGER NOT NULL REFERENCES users(id),comment TEXT NOT NULL,improvement_plan TEXT NOT NULL DEFAULT '',quality REAL CHECK(quality BETWEEN 0 AND 100),learning REAL CHECK(learning BETWEEN 0 AND 100),created_at TEXT NOT NULL);
CREATE TABLE reflections(id INTEGER PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id),start_date TEXT NOT NULL,end_date TEXT NOT NULL,self_assessment TEXT NOT NULL,next_plan TEXT NOT NULL,updated_at TEXT NOT NULL,UNIQUE(user_id,start_date,end_date));
CREATE TABLE overrides(id INTEGER PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id),start_date TEXT NOT NULL,end_date TEXT NOT NULL,score REAL NOT NULL CHECK(score BETWEEN 0 AND 100),reason TEXT NOT NULL,actor_id INTEGER NOT NULL REFERENCES users(id),created_at TEXT NOT NULL);
CREATE TABLE notifications(id INTEGER PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id),period TEXT NOT NULL,kind TEXT NOT NULL,title TEXT NOT NULL,message TEXT NOT NULL,created_at TEXT NOT NULL,read_at TEXT,email_status TEXT NOT NULL DEFAULT 'not_configured',delivered_at TEXT,UNIQUE(user_id,period,kind));
CREATE TABLE audit_logs(id INTEGER PRIMARY KEY,actor_id INTEGER REFERENCES users(id),action TEXT NOT NULL,entity TEXT NOT NULL,entity_id TEXT NOT NULL,before_json TEXT,after_json TEXT,created_at TEXT NOT NULL);
CREATE INDEX audit_time ON audit_logs(created_at);
CREATE TRIGGER audit_no_update BEFORE UPDATE ON audit_logs BEGIN SELECT RAISE(ABORT,'Audit events are immutable'); END;
CREATE TRIGGER audit_no_delete BEFORE DELETE ON audit_logs BEGIN SELECT RAISE(ABORT,'Audit events are immutable'); END;
CREATE TABLE report_revisions(id INTEGER PRIMARY KEY,report_id INTEGER NOT NULL REFERENCES reports(id),version INTEGER NOT NULL,snapshot TEXT NOT NULL,actor_id INTEGER NOT NULL REFERENCES users(id),created_at TEXT NOT NULL,UNIQUE(report_id,version));
